    "public_title_ur": "آن لائن تجارت کے مال اور قابلِ وصول رقوم پر زکوٰۃ کا حکم",
    "public_title_en": "Zakat on E-Commerce Inventory and Receivables",
    "public_question_text": "آن لائن تجارت میں گودام کے مال اور پلیٹ فارم پر موجود قابلِ وصول رقوم پر زکوٰۃ کا حساب کیسے کیا جائے گا؟",
    "public_answer_text": "بسم اللہ الرحمٰن الرحیم\n\nالجواب وباللہ التوفیق:\nصورتِ مسئولہ میں سالِ زکوٰۃ مکمل ہونے پر گودام میں موجود تمام مالِ تجارت کی موجودہ قیمتِ فروخت لگائی جائے گی۔ اسی طرح ای کامرس پلیٹ فارم یا گاہکوں کے ذمہ جو رقوم واجب الادا ہیں اور ان کی وصولی کی امید ہے (دیونِ قویہ)، انہیں بھی کل نصاب میں شامل کر کے مجموعی مالیت پر ڈھائی فیصد (2.5%) زکوٰۃ ادا کرنا شرعاً لازم ہے۔\n\nواللہ تعالیٰ اعلم بالصواب",
